. "$PSScriptRoot\Common.ps1"
function Import-CPAStackProxy { $p=Join-Path (Get-CPAStackRoot) 'config\proxy.psd1'; if (Test-Path $p) { $v=Import-PowerShellDataFile $p; foreach($n in 'https_proxy','http_proxy','all_proxy'){if($v[$n]){Set-Item "Env:$n" $v[$n]}} } }
function Set-CPAStackProxy([string]$Line) { if (!$Line) {$Line=Read-Host 'Optional proxy (export/set format, blank to skip)'}; if (!$Line) {return}; $h=@{}; [regex]::Matches($Line,'(?i)(https?_proxy|all_proxy)=([^\s]+)') | % {$h[$_.Groups[1].Value.ToLower()]=$_.Groups[2].Value}; if (!$h.Count -or @($h.Values | ? {$_ -notmatch '^(http|https|socks5)://' }).Count){throw 'Invalid proxy format.'}; "@{`n$($h.Keys|% {"  '$_' = '$($h[$_])'"}|Out-String)}`n" | Set-Content (Join-Path (Get-CPAStackRoot) 'config\proxy.psd1'); Import-CPAStackProxy }
function Invoke-CPAStackWeb([string]$Uri,[string]$OutFile) { Import-CPAStackProxy; try {Invoke-WebRequest $Uri -OutFile $OutFile -UseBasicParsing; return} catch {$code=$_.Exception.Response.StatusCode.value__; if($code -notin 401,403){throw}}; $tokenFile=Join-Path (Get-CPAStackRoot) 'config\github-token'; $token=if(Test-Path $tokenFile){Get-Content $tokenFile -Raw}else{Read-Host 'GitHub token'}; if(!$token){throw 'GitHub access denied and no token supplied.'}; Set-Content $tokenFile $token.Trim() -NoNewline; Invoke-WebRequest $Uri -OutFile $OutFile -UseBasicParsing -Headers @{Authorization="Bearer $($token.Trim())"} }
